<?php
namespace App\Filament\Admin\Resources\Renewals\Pages;use App\Filament\Admin\Concerns\ServiceValidation;use App\Filament\Admin\Resources\Renewals\RenewalResource;use App\Models\Policy;use Filament\Actions\Action;use Filament\Forms\Components\Select;use Filament\Resources\Pages\ViewRecord;final class ViewRenewal extends ViewRecord{protected static string $resource=RenewalResource::class;protected function getHeaderActions():array{return[Action::make('quote')->icon('heroicon-o-calculator')->visible(fn()=>in_array($this->record->status,['DUE','CONTACTED'],true))->action(function(){if(ServiceValidation::run(fn()=>app(\App\Application\Policies\RenewalService::class)->createQuote($this->record,auth()->user()))===null)return;}),Action::make('complete')->label('Link successor')->icon('heroicon-o-link')->color('success')->visible(fn()=>$this->record->status==='QUOTED')->schema([Select::make('successor_policy_id')->options(fn()=>Policy::where(['tenant_id'=>$this->record->tenant_id,'previous_policy_id'=>$this->record->policy_id,'status'=>'ACTIVE'])->pluck('policy_number','id'))->required()->searchable()])->action(function(array$d){if(ServiceValidation::run(fn()=>app(\App\Application\Policies\RenewalService::class)->complete($this->record,Policy::findOrFail($d['successor_policy_id'])))===null)return;})];}}
